import React from 'react';
import styled from 'styled-components';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { WithChildren } from '../../core/types/with-children.js';
import { getTextStyle } from '../../core/utils/styles/text-styles.js';

//#region Typings
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface ContentProps extends WithChildren, StylingProps, DataTestId {}
//#endregion Typings

//#region StyledComponents
const StyledContent = /* @__PURE__ */ styled.div({
  overflowY: 'auto',
  overflowX: 'hidden',
  ...getTextStyle('base'),
});
//#endregion StyledComponents

/** The content of the guided interaction overlays. */
export const Content = (props: ContentProps) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;
  return (
    <StyledContent
      data-testid={dataTestId}
      className={consumerClassName}
      style={consumerStyle}
    >
      {children}
    </StyledContent>
  );
};

Content['displayName'] = 'GuidedInteraction.Content';
